import './axiom-fit.js';
import { t } from './i18n.js';
import { esc, specList, tagLine, roomTitle, linkButton, insideButton, label } from './exhibit-frame.js';

// The plotted observations are the app's bundled Hooke's-law teaching example.
export function axiomPlot() {
  const force=[.51,.98,1.53,2.01,2.48,3.05,3.47,4.04,4.48,5.03,5.49,6.02];
  return `<svg class="axiom-plot" viewBox="0 0 400 280" aria-hidden="true"><g class="axiom-grid">${[70,130,190].map(y=>`<path d="M40 ${y}H372"/>`).join('')}${[120,200,280,360].map(x=>`<path d="M${x} 30V230"/>`).join('')}</g><path class="axiom-axis" d="M40 30V230H372"/><g class="axiom-axis-label"><text x="10" y="14">F / N</text><text x="327" y="260">x / m</text><text x="23" y="234">0</text><text x="17" y="134">3</text><text x="17" y="48">6</text><text x="150" y="249">0.05</text><text x="276" y="249">0.10</text></g><path class="axiom-fit" pathLength="1" d="M40 229.873L365 35.920"/><g class="axiom-observations">${force.map((y,i)=>{const x=40+(i+1)*26,cy=230-y*31;return `<g style="--point:${i}"><path d="M${x-4} ${cy}h8M${x} ${cy-4}v8"/><circle cx="${x}" cy="${cy}" r="4"/></g>`}).join('')}</g><path class="axiom-gradient" d="M144 168H300V75"/><text x="214" y="189" class="axiom-gradient-label">Δy / Δx</text></svg>`;
}
const stats=()=>`<dl class="axx-stats"><div><dt>09</dt><dd>${t('axiom.charts')}</dd></div><div><dt>22</dt><dd>${t('axiom.formulas')}</dd></div><div><dt>03</dt><dd>${t('axiom.modes')}</dd></div></dl>`;
const actions=project=>`<div class="xr-actions">${linkButton({href:project.liveUrl,text:t('axiom.launch'),primary:true})}${linkButton({href:project.repoUrl,text:'GitHub'})}</div><p class="xr-aside">${t('axiom.local')}</p>`;
const figure=()=>`<figure class="axx-figure" aria-hidden="true"><div class="axx-figure-head"><span>Figure / 01</span><b>F = kx</b></div>${axiomPlot()}<figcaption><span>${t('axiom.figure')}</span><span class="xr-data">12 observations</span></figcaption></figure>`;

export function axiomCard(project) {
  return `<article class="exhibit xr xr--axiom" id="project-axiom"><div class="xr-inner"><div class="xr-hero"><div class="xr-copy">${roomTitle('AXIOM','03')}<p class="axx-motto">Measure. Plot. Discover.</p><p class="axx-name">${t('axiom.name')}</p><p class="xr-sub">${t('axiom.headline')}</p><p class="xr-lede">${t('axiom.description')}</p>${specList([[label.exhibit(),'No. 03'],[label.category(),esc(project.category)],[label.version(),'<span class="xr-data">1.0</span>'],[label.stack(),tagLine(project.tags)]])}${actions(project)}<div class="xr-actions xr-actions--inside">${insideButton('axiom',t('axiom.inspect'),t('project.viewAria',{name:'AXIOM'}))}</div></div><div class="xr-stage axx-stage">${figure()}</div></div><div class="axx-lab"><figure class="axx-window"><div class="axx-window-bar"><b>A</b><span>AXIOM / The workspace</span><span class="axx-modes"><span>Research</span><span>IB student</span><span>Professional</span></span></div><img src="./assets/projects/axiom/workspace.png" width="2283" height="1437" alt="${t('axiom.capture')}" loading="lazy" decoding="async"><figcaption><span class="xr-data">Figure / 02</span><span>${t('axiom.capture')}</span></figcaption></figure>${stats()}</div><footer class="xr-foot"><span>The scientific collection</span><span>No. 03 / V1.0</span><span>CHEFZC © 2026</span></footer></div></article>`;
}
export function axiomDetail(project) {
  return `<div class="xd xd--axiom"><header class="xd-head">${roomTitle('AXIOM','03',{tag:'h2',id:'dialog-title'})}<p class="xr-sub">${t('axiom.headline')}</p>${specList([[label.exhibit(),'ChefZC / Project 03'],[label.version(),'<span class="xr-data">1.0.0</span>'],[label.category(),t('axiom.name')],[label.stack(),tagLine(project.tags)]])}</header><figure class="xd-shot axx-detail-shot"><img src="./assets/projects/axiom/workspace.png" width="2283" height="1437" alt="${t('axiom.capture')}"><figcaption>${t('axiom.capture')}</figcaption></figure>${stats()}<div class="xd-copy"><section><span class="xd-step">01 / The experiment</span><div><h3>${t('axiom.detailTitle')}</h3><p>${t('axiom.detailText')}</p></div></section><section><span class="xd-step">02 / Beyond the screen</span><div><h3>${t('axiom.export')}</h3><p>${t('axiom.exportText')}</p></div></section></div><p class="xd-note">${t('axiom.boundary')}</p><div class="xd-actions">${actions(project)}</div></div>`;
}
